// data/cities.ts
/**
 * India administrative divisions: States/UTs > Districts > Sub-districts
 * (tehsil / taluka / mandal / circle, as listed in the Local Government Directory).
 *
 * Source: Local Government Directory (LGD), Government of India (GODL-India),
 * via github.com/planemad/india-local-government-directory.
 * Counts: 36 states/UTs, 763 districts, 6921 sub-districts.
 *
 * NOTE: This is a snapshot. Districts created after it was taken will be missing and
 * some newer districts have an empty subDistricts list. Re-export from
 * lgdirectory.gov.in when you need the latest list.
 */

export interface SubDistrict {
  name: string;
  slug: string;
  /** LGD sub-district code */
  code: number;
}

export interface District {
  name: string;
  slug: string;
  /** LGD district code */
  code: number;
  subDistricts: SubDistrict[];
}

export interface State {
  name: string;
  slug: string;
  /** LGD state code */
  code: number;
  type: "state" | "ut";
  districts: District[];
}

