/* ---------- Helpers for generateStaticParams() and index pages ---------- */

export const getState = (stateSlug: string) =>
  indiaStates.find((s) => s.slug === stateSlug);

export const getDistrict = (stateSlug: string, districtSlug: string) =>
  getState(stateSlug)?.districts.find((d) => d.slug === districtSlug);

export const getSubDistrict = (stateSlug: string, districtSlug: string, subSlug: string) =>
  getDistrict(stateSlug, districtSlug)?.subDistricts.find((x) => x.slug === subSlug);

/** [{ state }] */
export const stateParams = indiaStates.map((s) => ({ state: s.slug }));

/** [{ state, district }] */
export const districtParams = indiaStates.flatMap((s) =>
  s.districts.map((d) => ({ state: s.slug, district: d.slug }))
);

/** [{ state, district, subdistrict }] */
export const subDistrictParams = indiaStates.flatMap((s) =>
  s.districts.flatMap((d) =>
    d.subDistricts.map((x) => ({ state: s.slug, district: d.slug, subdistrict: x.slug }))
  )
);

export default indiaStates;